INSERT INTO parameter_criteria_details (id, parameter_criteria_id, criteria, level, created_at, updated_at, deleted_at) VALUES
  (1, 1, 'Belum ada program penanaman budaya Risiko, misal risk awards, sosialisasi, risk townhall, dan sebagainya', 1, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL),
  (2, 1, 'Telah ada program penanaman budaya Risiko (misal risk awards, sosialisasi risk townhall, dan sebagainya), namun saat ini program hanya dilakukan sesekali, tidak rutin atau berkala', 2, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL),
  (3, 1, 'Telah ada program penanaman budaya Risiko yang sedang dijalankan (misal risk awards, sosialisasi risk townhall, dan sebagainya) dan terdapat program sadar Risiko, saat ini dilakukan secara rutin (satu kali dalam setahun)', 3, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL),
  (4, 1, 'Telah ada program penanaman budaya Risiko yang sedang dijalankan (misal risk awards, sosialisasi risk townhall, dan sebagainya) dan terdapat program sadar Risiko yang saat ini dilakukan secara rutin dan lebih sering (lebih dari satu kali dalam setahun)', 4, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL),
  (5, 1, 'Telah ada program penanaman budaya Risiko yang sedang dijalankan (misal risk awards, sosialisasi risk townhall, dan sebagainya) dan terdapat program sadar Risiko, saat ini dilakukan secara rutin dan lebih sering (lebih dari satu kali dalam setahun) ', 5, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL),
  (6, 2, 'Budaya Risiko belum tertanam di kegiatan usaha sehari-hari (misal kepemilikan dan tanggung jawab Risiko pegawai dan jajaran manajemen belum jelas). Tanggung jawab pengembangan budaya Risiko diemban oleh pegawai tertentu (misal unit kerja khusus), namun tidak ada keterlibatan Lini Kedua dan Direksi', 1, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL),
  (7, 2, 'Tanggung jawab pengembangan budaya Risiko diemban oleh Lini Kedua namun tidak tercantum dengan jelas peran dan tanggung jawab dalam uraian jabatan Lini Kedua', 2, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL),
  (8, 2, 'Tanggung jawab pengembangan budaya Risiko secara jelas diemban oleh Lini Kedua dan sudah tercantum dengan jelas dalam uraian jabatan Lini Kedua, serta di awasi oleh Direksi dan Dewan Komisaris/ Dewan Pengawas', 3, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL),
  (9, 2, 'Tanggung jawab pengembangan budaya Risiko secara jelas diemban oleh Lini Kedua dan tercantum dalam uraian jabatan Lini Kedua serta di awasi oleh Direksi dan Dewan Komisaris/ Dewan Pengawas', 4, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL),
  (10, 2, 'Tanggung jawab pengembangan budaya Risiko secara jelas diemban dan tercantum dalam uraian jabatan tidak hanya untuk Lini Kedua, tetapi juga di semua lini (khususnya yang memegang posisi manajerial)', 5, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL),
  (11, 3, 'Direksi belum berperan aktif untuk mengembangkan budaya Manajemen Risiko', 1, '2025-05-05 04:53:04', '2025-05-05 04:53:04', NULL),
  (12, 3, 'Direksi belum berperan aktif untuk mengembangkan budaya Manajemen Risiko', 2, '2025-05-05 04:53:04', '2025-05-05 04:53:04', NULL),
  (13, 3, 'Direksi berperan aktif untuk mengembangkan budaya Manajemen Risiko', 3, '2025-05-05 04:53:04', '2025-05-05 04:53:04', NULL),
  (14, 3, 'Direksi berperan aktif untuk mengembangkan budaya Manajemen Risiko', 4, '2025-05-05 04:53:04', '2025-05-05 04:53:04', NULL),
  (15, 3, 'Direksi berperan aktif untuk mengembangkan budaya Manajemen Risiko', 5, '2025-05-05 04:53:04', '2025-05-05 04:53:04', NULL),
  (16, 4, 'Telah ada evaluasi rutin yang dilakukan minimal 1 kali per tahun terhadap peningkatan budaya Risiko (misal survei budaya Risiko) termasuk mengumpulkan masukan dari pegawai untuk pengembangan program budaya Risiko', 4, '2025-05-05 04:57:46', '2025-05-05 04:57:46', NULL),
  (17, 4, 'Telah ada evaluasi rutin yang dilakukan minimal 1 kali per tahun terhadap peningkatan budaya Risiko (misal survei budaya Risiko) termasuk mengumpulkan masukan dari pegawai untuk pengembangan program budaya Risiko', 5, '2025-05-05 04:57:46', '2025-05-05 04:57:46', NULL),
  (26, 7, 'Budaya Risiko menjadi bagian integral dari budaya perusahaan. Budaya Risiko tercantum pada kebijakan budaya kerja yang disosialisasikan di perusahaan, dan budaya ini tertanam di seluruh lini perusahaan dimulai dengan penegasan dari jajaran manajemen, diperkuat dengan langkah nyata (yang juga dapat digunakan sebagai kriteria evaluasi kinerja pegawai):
- Cepat mengantisipasi potensi Risiko dan menanggapinya dengan tepat
- Menyeimbangkan target jangka pendek dan Risiko jangka panjang
- Pembahasan Risiko yang sulit tetap dilakukan secara konstruktif
- Mendukung pelaksanaan inisiatif Manajemen Risiko dan secara ketat menerapkan pedoman Manajemen Risiko
- Resiliensi (contohnya resiliensi operasional, tanggap merespon peristiwa yang merugikan, dan sebagainya, dengan memberi penekanan baik dalam penyusunan strategi maupun dalam pelaksanaannya)', 4, '2025-08-19 19:35:01', '2025-08-19 19:35:01', NULL),
  (27, 7, 'Budaya Risiko menjadi bagian integral dari budaya perusahaan. Budaya Risiko tercantum pada kebijakan budaya kerja yang disosialisasikan di perusahaan, dan budaya ini tertanam di seluruh lini perusahaan dimulai dengan penegasan dari jajaran manajemen, diperkuat dengan langkah nyata (yang juga dapat digunakan sebagai kriteria evaluasi kinerja pegawai):
- Cepat mengantisipasi potensi risiko dan menanggapinya dengan tepat
- Menyeimbangkan target jangka pendek dan Risiko jangka panjang
- Pembahasan Risiko yang sulit tetap dilakukan secara konstruktif
- Mendukung pelaksanaan inisiatif Manajemen Risiko dan secara ketat menerapkan pedoman Manajemen Risiko
-Resiliensi (contohnya resiliensi operasional, tanggap merespon peristiwa yang merugikan, dan sebagainya, dengan memberi penekanan baik dalam penyusunan strategi maupun dalam pelaksanaannya)', 5, '2025-08-19 19:35:01', '2025-08-19 19:35:01', NULL),
  (28, 8, 'Telah ada serangkaian sistem penunjang untuk pelaksanaan dan penanaman program budaya Risiko perusahaan, contohnya:
- Intranet perusahaan untuk memuat informasi yang dapat diakses mengenai program budaya Risiko dan kebijakan Risiko perusahaan
- Tersedia dashboard untuk memantau metrik yang berkaitan dengan budaya Risiko/program budaya Risiko', 5, '2025-08-19 19:36:04', '2025-08-19 19:36:04', NULL),
  (29, 9, 'Telah ada bukti yang jelas atas kinerja implementasi program budaya Risiko, di antaranya:
- Bukti perbaikan indikator utama berkaitan dengan budaya Risiko perusahaan, di antaranya penurunan jumlah kasus kecurangan internal, korupsi, pelanggaran kode etik pegawai, dan penurunan jumlah kerugian dari kasus pelanggaran tersebut
- Penyelesaian program budaya risiko yang telah direncanakan ', 5, '2025-08-19 19:36:57', '2025-08-19 19:36:57', NULL),
